typedef struct {
    int key;
    int value;
} Entry;

int hash_lookup(Entry *table, int size, int key) {
    int index = key % size;
    while (table[index].key != 0) {
        if (table[index].key == key) {
            return table[index].value;
        }
        index = (index + 1) % size;
    }
    return -1;
}

int binary_search(int *arr, int size, int target) {
    int left = 0, right = size - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] == target) return mid;
        if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return -1;
}

void bubble_sort(int *arr, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

typedef struct block {
    int size;
    int allocated;
    struct block *next;
} Block;

Block *heap = NULL;

void* simple_malloc(int size) {
    Block *block = heap;
    while (block != NULL) {
        if (!block->allocated && block->size >= size) {
            block->allocated = 1;
            return (void *)(block + 1);
        }
        block = block->next;
    }
    return NULL;
}

